style.css:
@-moz-document url-prefix("https://docs.google.com/document/") {
/* Overall background image */
    html, body {
        background-image: url('https://img.pikbest.com/wp/202405/mushroom-forest-a-stunning-display-of-glowing-mushrooms-in-fantasy-3d-illustration_9793603.jpg!bw700') !important;
        background-size: cover !important;
        background-position: center !important;
        background-repeat: no-repeat !important;
        background-attachment: fixed !important;
    }

    /* Make surrounding areas transparent to show the background image */
    .kix-appview-editor {
        background-color: transparent !important;
    }

    /* Dark grey paper (document page) */
    .kix-page {
        background-color: #333333 !important;
        box-shadow: none !important; /* Optional: removes page shadow for better blending */
    }

    /* Adjust text color for readability on dark grey */
    .kix-paragraphrenderer, .kix-lineview-text-block, .kix-wordhtmlgenerator-word-node {
        color: #ffffff !important;
    }

    /* Optional: Darken other UI elements for consistency */
    .docs-editor {
        background-color: #333333 !important;
    }
    .navigation-widget {
        background-color: #222222 !important;
    }
    .docs-titlebar-buttons {
        background-color: #222222 !important;
    }
}
